// Üretilen dosya: tool/ozgun/uret.py. Coğrafya · Toprak tipleri, kayaç döngüsü ve karstik-buzul-rüzgâr-kıyı yer şekilleri (çernozyom, terra rossa, lapya, polye, obruk, falez, tombolo, lagün, fiyort, moren) (kolay).
const ozGeography17Kolay = <(String, String, List<String>, String)>[
  ('Yerin derinliklerindeki magmanın yer kabuğu içerisindeki boşluklarda yavaşça soğuyup katılaşmasıyla oluşan derinlik püskürük kayacı aşağıdakilerden hangisidir?', 'Granit', ['Bazalt', 'Obsidiyen', 'Mermer'], 'Granit, magmanın yer kabuğu içinde yavaş soğumasıyla oluşan iri kristalli bir iç püskürük kayaçtır.'),
  ('Volkanik patlamalar sırasında yüzeye çıkan lavların ani olarak soğumasıyla oluşan, camsı ve parlak yapılı dış püskürük kayaç hangisidir?', 'Obsidiyen', ['Siyenit', 'Kalker', 'Gnays'], 'Obsidiyen yani volkan camı, lavların yüzeyde çok hızlı soğumasıyla kristalleşmeden oluşan dış püskürük bir kayaçtır.'),
  ('Kalker (kireç taşı) kayacının yüksek sıcaklık ve basınç altında başkalaşıma uğramasıyla oluşan metamorfik kayaç aşağıdakilerden hangisidir?', 'Mermer', ['Kuvarsit', 'Elmas', 'Şist'], 'Kimyasal tortul bir kayaç olan kalker, yüksek sıcaklık ve basınç altında kristalleşerek mermere dönüşür.'),
  ('Bitki kalıntılarının havasız ortamlarda uzun jeolojik dönemler boyunca birikip taşlaşmasıyla oluşan organik tortul kayaç türü hangisidir?', 'Taş kömürü', ['Jips', 'Traverten', 'Andezit'], 'Taş kömürü, linyit ve turba gibi kayaçlar bitkisel kalıntıların karbonlaşmasıyla oluşan organik tortul kayaçlardır.'),
  ('Suda kolay çözünebilen kayaçların bulunduğu karstik arazilerde yaygın olarak görülen kimyasal tortul kayaç aşağıdakilerden hangisidir?', 'Kalker', ['Konglomera', 'Gabro', 'Bazalt'], 'Kalker (kireç taşı), jips (alçı taşı) ve kaya tuzu suda çözünebilen başlıca kimyasal tortul kayaçlardır.'),
  ('İç püskürük kayaçların dış püskürük kayaçlara göre daha iri kristalli bir yapıya sahip olmasının temel nedeni nedir?', 'Magmanın yer altında yavaş soğuması', ['Yüzeyde rüzgar erozyonuna uğramaları', 'Bünyelerinde fosil bulundurmaları', 'Akarsular tarafından taşınmış olmaları'], 'Magma yerin derinliklerinde yavaş soğuduğu için minerallerin büyüyüp iri kristaller oluşturmasına yeterli zaman kalır.'),
  ('Volkanlardan çıkan kül, kum ve toz boyutundaki ince malzemelerin üst üste birikip hafifçe çimentolaşmasıyla oluşan kayaç hangisidir?', 'Volkan tüfü', ['Diyorit', 'Brez', 'Kuvarsit'], 'Volkan tüfü, volkanik patlamalarla savrulan kül ve ince materyallerin yığılıp sıkışmasıyla oluşan yumuşak bir dış püskürük kayaçtır.'),
  ('Granit kayacının yer kabuğunun derinliklerinde yüksek sıcaklık ve basınç etkisiyle değişime uğraması sonucu hangi kayaç oluşur?', 'Gnays', ['Mermer', 'Kuvarsit', 'Tebeşir'], 'İç püskürük bir kayaç olan granit, yüksek basınç ve sıcaklık altında başkalaşarak yapraklı dokulu gnaysa dönüşür.'),
  ('Akarsu, rüzgar veya buzulların aşındırdığı kum boyutundaki tanelerin doğal bir çimento ile birleşmesiyle oluşan fiziksel tortul kayaç hangisidir?', 'Kumtaşı', ['Kaya tuzu', 'Mercan kalkeri', 'Peridotit'], 'Kumtaşı (gre), kırıntılı yani fiziksel (mekanik) tortul kayaçların en tipik örneklerinden biridir.'),
  ('Aşağıdaki kayaç gruplarından hangisinin içerisinde geçmiş dönemlerde yaşamış canlılara ait fosil kalıntılarına rastlanma olasılığı en yüksektir?', 'Tortul kayaçlar', ['İç püskürük kayaçlar', 'Dış püskürük kayaçlar', 'Damar püskürük kayaçları'], 'Tortul kayaçlar tabakalı yapıya sahiptir ve oluşumları sırasında canlı kalıntılarının çökelmesiyle fosil barındırırlar.'),
  ('Sıcak su kaynaklarının yeryüzüne çıktığı yerlerde suyun içindeki kalsiyum bikarbonatın çökelmesiyle oluşan basamaklı beyaz kayaç hangisidir?', 'Traverten', ['Obsidiyen', 'Kil taşı', 'Antrasit'], 'Denizli Pamukkale\'de tipik örnekleri görülen traverten, kalsiyum karbonatın çökelmesiyle oluşan kimyasal tortul bir kayaçtır.'),
  ('Kil taşının yüksek sıcaklık ve özellikle yüksek basınç altında başkalaşım geçirmesiyle oluşan yapraklı yapıdaki kayaç hangisidir?', 'Şist', ['Siyenit', 'Konglomera', 'Sünger taşı'], 'Fiziksel tortul bir kayaç olan kil taşı, metamorfizma sonucunda şist adı verilen başkalaşım kayacına dönüşür.'),
  ('Gaz boşlukları bakımından çok zengin olan, suda yüzebilecek kadar hafif ve gözenekli dış püskürük kayaç aşağıdakilerden hangisidir?', 'Sünger taşı (Pomza)', ['Gabro (ağır derinlik kayacı)', 'Mermer (kristalli başkalaşım kayacı)', 'Çakmaktaşı (sert kimyasal tortul)'], 'Pomza (sünger taşı), lavların hızla soğurken içindeki gazların çıkmasıyla gözenekli bir yapı kazanan hafif volkanik kayaçtır.'),
  ('Kayaç döngüsü sürecinde her tür kayacın levha hareketleriyle manto katmanına dalarak aşırı ısınması sonucunda ne meydana gelir?', 'Magmaya dönüşerek erime', ['Doğrudan organik tortulaşma', 'Tabakalı fosil birikimi', 'Fiziksel ufalanma ile kumlaşma'], 'Kayaç döngüsünde magmatik, tortul veya başkalaşım kayaçlar mantoya daldıklarında eriyerek yeniden magmaya dönüşürler.'),
  ('Yuvarlak çakılların doğal bir bağlayıcı madde (çimento) ile birleşip taşlaşması sonucu oluşan fiziksel tortul kayaç hangisidir?', 'Konglomera', ['Jips', 'Andezit', 'Elmas'], 'Konglomera (çakıl taşı), akarsu veya dalgaların yuvarlaklaştırdığı çakılların çimentolaşmasıyla oluşan kırıntılı tortul kayaçtır.'),
  ('Toprağın oluşumunda ana kayanın açık renkli veya koyu renkli minerallerden meydana gelmesi doğrudan hangi fiziksel özelliği etkiler?', 'Toprağın rengini ve ısınma özelliğini', ['Bölgedeki yıllık yağış rejimini', 'Arazinin deniz seviyesinden yükseltisini', 'Bulunduğu enlem derecesini'], 'Ana kayanın mineral bileşimi toprağın rengini, dokusunu, geçirgenliğini ve mineral zenginliğini doğrudan etkiler.'),
  ('Toprağın en üst katmanında bitki ve hayvan kalıntılarının mikroorganizmalar tarafından parçalanmasıyla oluşan koyu renkli organik maddeye ne ad verilir?', 'Humus', ['Regolit', 'Ana kaya', 'Kalker yumrusu'], 'Humus, bitki ve hayvan atıklarının toprakta çürümesiyle oluşan, toprağa koyu renk ve yüksek verimlilik kazandıran organik maddedir.'),
  ('Fiziksel (mekanik) çözülmenin en şiddetli olduğu iklim bölgelerinin temel özelliği aşağıdakilerden hangisidir?', 'Günlük sıcaklık farkının yüksek, nemin az olması', ['Yıl boyunca bol yağışlı ve bulutlu olması', 'Sıcaklığın yıl boyu sıfırın altında kalması', 'Bitki örtüsünün gür yağmur ormanları olması'], 'Çöl ve karasal iklim bölgelerinde nem az, günlük sıcaklık farkı çok yüksek olduğu için kayaçlar genleşip büzülerek fiziksel yolla ufalanır.'),
  ('Kimyasal çözülmenin en hızlı ve etkili şekilde gerçekleştiği iklim bölgesi aşağıdakilerden hangisidir?', 'Ekvatoral iklim bölgesi', ['Kutup iklimi bölgesi', 'Tundra iklimi bölgesi', 'Orta kuşak çöl bölgesi'], 'Kimyasal çözülme için yüksek sıcaklık ve bol su (yağış/nem) gerekir; bu koşullar yıl boyu Ekvatoral iklimde en üst düzeydedir.'),
  ('Yerli (zonal) toprakların yukarıdan aşağıya doğru sıralanan katmanlarına (A, B, C, D) coğrafyada ne ad verilir?', 'Horizon', ['Alüvyon', 'Moren', 'Fay aynası'], 'Tam gelişmiş bir toprak profilinde birbirinden fiziksel ve kimyasal özellikleriyle ayrılan katmanlara horizon denir.'),
  ('Toprak profilinde yıkanma katmanı olarak bilinen, organik madde ve canlı faaliyetinin en yoğun olduğu en üst katman hangisidir?', 'A horizonu', ['B horizonu', 'C horizonu', 'D horizonu'], 'A horizonu toprağın en üst katmanıdır; canlıların yaşadığı, humusun bulunduğu ve yağış sularıyla yıkanmanın gerçekleştiği katmandır.'),
  ('Akarsuların aşındırıp taşıdığı ince malzemeleri eğimin azaldığı ova ve delta tabanlarında biriktirmesiyle oluşan çok verimli toprak hangisidir?', 'Alüvyal topraklar', ['Laterit topraklar', 'Tundra toprakları', 'Podzol topraklar'], 'Alüvyal topraklar, akarsuların farklı bölgelerden taşıdığı minerallerce zengin malzemelerin birikmesiyle oluşan azonal (taşınmış) topraklardır.'),
  ('Akdeniz iklim bölgesinde kızılçam ve maki örtüsü altında, kalker (kireç taşı) kayacının çözünmesiyle oluşan demir oksitçe zengin kırmızı toprak hangisidir?', 'Terra rossa (Kırmızı Akdeniz toprağı)', ['Çernozyom (Kara topraklar)', 'Kahverengi step toprakları', 'Kül renkli podzol topraklar'], 'Terra rossa, Akdeniz ikliminde kalker üzerinde gelişen ve içindeki demir bileşiklerinin oksitlenmesiyle kırmızı renk alan zonal topraktır.'),
  ('Dünyanın en verimli yerli (zonal) toprağı kabul edilen, Türkiye\'de Erzurum-Kars platosunda çayır bitki örtüsü altında gelişen koyu renkli toprak hangisidir?', 'Çernozyom', ['Çöl toprakları', 'Sierozem toprakları', 'Tundra toprakları'], 'Çernozyom (kara toprak), sert karasal iklimde gür dağ çayırlarının soğuk nedeniyle yavaş ayrışması sonucu bol humus biriktiren çok verimli topraktır.'),
  ('Soğuk ve nemli iklim bölgelerinde iğne yapraklı (tayga) ormanlar altında gelişen, aşırı yıkanmış kül renkli ve asidik toprak hangisidir?', 'Podzol', ['Terra rossa', 'Kestane renkli bozkır', 'Vertisol'], 'Podzol topraklar, soğuk ve nemli bölgelerde (Türkiye\'de Batı Karadeniz\'in yüksek kesimlerinde) iğne yapraklı ormanlar altında oluşan kül renkli topraklardır.'),
  ('Yeryüzünde ilk oluşan ve diğer tüm kayaçların kökenini teşkil ettiği için "ana kayaç" olarak adlandırılan kayaç grubu hangisidir?', 'Püskürük (magmatik) kayaçlar', ['Fiziksel tortul kayaçlar', 'Kimyasal tortul kayaçlar', 'Organik tortul kayaçlar'], 'Dünya\'nın ilk soğuma sürecinde magmanın katılaşmasıyla oluşan magmatik kayaçlar, diğer kayaç gruplarının da kökenini oluşturan ana kayaçlardır.'),
  ('Çanak-çömlek, tuğla, kiremit ve seramik yapımında temel hammadde olarak kullanılan ince taneli fiziksel tortul kayaç ve toprak malzemesi hangisidir?', 'Kil (veya kil taşı)', ['Obsidiyen (volkan camı)', 'Kaya tuzu (halit)', 'Antrasit (taş kömürü)'], 'Suyla karıştığında şekil alabilen ve pişirildiğinde sertleşen kil ve kil taşı, tuğla, kiremit ve seramik sanayisinin temel hammaddesidir.'),
  ('Tarih öncesi çağlarda insanların kesici ve delici alet (ok ucu, mızrak, bıçak) yapımında en çok tercih ettiği camsı volkanik kayaç hangisidir?', 'Obsidiyen', ['Tebeşir', 'Jips', 'Volkan tüfü'], 'Obsidiyen kırıldığında çok keskin kenarlar oluşturduğu için Taş Devri insanları tarafından kesici ve delici alet yapımında yaygın kullanılmıştır.'),
  ('Mağara tavanlarından damlayan kireçli suların oluşturduğu sarkıt, dikit ve sütunlar hangi kayaç grubuna örnektir?', 'Kimyasal tortul kayaçlar', ['İç püskürük kayaçlar', 'Başkalaşım kayaçları', 'Organik tortul kayaçlar'], 'Mağaralardaki sarkıt, dikit ve sütunlar yer altı sularındaki kalsiyum karbonatın çökelmesiyle oluşan kimyasal tortul (karstik) oluşumlardır.'),
  ('Kömür türleri arasında jeolojik olarak en genç olan, bataklıklardaki bitki kalıntılarının henüz tam taşlaşmamış haline ne ad verilir?', 'Turba', ['Antrasit', 'Taş kömürü', 'Elmas'], 'Karbonlaşma derecesi en düşük ve oluşumu en genç olan organik tortul yakıt turbadır; onu sırasıyla linyit, taş kömürü ve antrasit izler.'),
  ('Termik santrallerde elektrik üretimi amacıyla Türkiye\'de en yaygın kullanılan Üçüncü Jeolojik Zaman (Tersiyer) oluşumlu organik tortul kayaç hangisidir?', 'Linyit', ['Mermer', 'Traverten', 'Granit'], 'Türkiye arazisinin büyük bölümü Tersiyer\'de şekillendiği için ülkemizde linyit yatakları çok yaygındır ve termik santrallerde kullanılır.'),
  ('İnşaat ve heykelcilik alanında antik çağlardan beri en çok tercih edilen, Afyonkarahisar ve Marmara Adası\'nda zengin yatakları bulunan başkalaşım kayacı hangisidir?', 'Mermer', ['Konglomera', 'Kaya tuzu', 'Linyit'], 'Kalkerin başkalaşımıyla oluşan mermer, kolay işlenebilmesi ve cilalandığında parlaması nedeniyle heykelcilik ve mimaride çok değerlidir.'),
  ('Magmanın yer kabuğu içerisindeki çatlaklara ve tabakalar arasına sokularak yüzey ile derinlik arasında katılaşmasıyla oluşan kayaçlara ne ad verilir?', 'Damar (yarı derinlik) kayaçları', ['Kimyasal çökel kayaçları', 'Biyojenik (organik) kayaçlar', 'Rüzgar birikinti kayaçları'], 'Yüzeye ulaşamadan yer kabuğunun sığ çatlaklarında (dayk, sill) soğuyan porfiri dokulu magmatik kayaçlara damar (yarı derinlik) kayaçları denir.'),
  ('Çukurova, Bafra ve Çarşamba gibi delta ovalarında yaygın olarak görülen ve tarımsal verimi çok yüksek olan toprak tipi hangisidir?', 'Alüvyal topraklar', ['Tundra toprakları', 'Podzol topraklar', 'Çöl toprakları'], 'Akarsuların taşıdığı verimli alüvyonların deniz kıyısında birikmesiyle oluşan delta ovaları alüvyal topraklarla kaplıdır.'),
  ('Kurak bölgelerde bitki örtüsünün cılız olması ve yağışın yetersizliği nedeniyle humus oranı çok düşük, tuz ve kireç oranı yüksek olan toprak hangisidir?', 'Çöl toprakları', ['Çernozyom toprakları', 'Kahverengi orman toprakları', 'Alüvyal vadi toprakları'], 'Çöl ikliminde bitki örtüsü yok denecek kadar cılız olduğundan toprakta humus oluşamaz; şiddetli buharlaşmayla yüzeyde tuz ve kireç kabukları birikir.'),
  ('İç Anadolu ve Güneydoğu Anadolu gibi bozkır alanlarında küçükbaş hayvancılık ve kuru tahıl tarımı yapılan zonal toprak tipi hangisidir?', 'Kahverengi ve kestane renkli bozkır toprakları', ['Kül renkli soğuk podzol toprakları', 'Kırmızı renkli ekvatoral laterit toprakları', 'Kutup altı donmuş tundra toprakları'], 'Yarı kurak step (bozkır) ikliminin karakteristik yerli toprağı kahverengi ve kestane renkli bozkır toprakları olup tahıl tarımına uygundur.'),
  ('Toprağın üst kısmının bitki örtüsünün tahrip edilmesi sonucu su ve rüzgar tarafından süpürülerek taşınması olayına ne ad verilir?', 'Erozyon', ['Heyelan', 'Metamorfizma', 'Karstlaşma'], 'Doğal dengenin bozulmasıyla toprağın verimli A horizonunun akarsu, sel suları ve rüzgarlarla aşındırılıp taşınmasına erozyon denir.'),
  ('Bitki köklerinin kayaç çatlakları arasına girerek büyümesi ve kayacı parçalaması hangi tür çözülme kapsamında değerlendirilir?', 'Biyolojik (organik) çözülme', ['Derinlik başkalaşımı', 'Volkanik püskürme', 'Buharlaşmalı çökelme'], 'Canlıların (özellikle ağaç köklerinin çatlakları genişletmesi veya likenlerin salgıladığı asitler) kayaçları parçalamasına biyolojik çözülme denir.'),
  ('Sağlam ve ayrışmamış ana kayanın yer aldığı, toprak profilinin en altındaki tabaka hangi harfle gösterilir?', 'D (veya R) horizonu', ['A horizonu', 'B horizonu', 'O horizonu'], 'Toprak profilinde en üstte O ve A, ortada B, onun altında iri kayaç parçalı C ve en altta sağlam ana kayayı simgeleyen D (R) horizonu bulunur.'),
  ('Dağ eteklerindeki kolüvyal toprakların üzerindeki ince unsurların sel sularıyla yıkanıp gitmesi sonucu geride kalan iri taşlı topraklara ne ad verilir?', 'Litosol (Taşlı topraklar)', ['Alüvyal (İnce vadi toprağı)', 'Çernozyom (Kara toprak)', 'Hidromorfik (Bataklık toprağı)'], 'Eğimli yamaçlarda erozyonla ince toprağın taşınması ve geriye köşeli, iri taşlı materyalin kalmasıyla oluşan azonal topraklara litosol denir.'),
  ('Çakmaktaşı (sileks) ve opal gibi silis bileşimli çökel kayaçlar oluşum kökenine göre hangi kayaç grubunda yer alır?', 'Kimyasal tortul kayaçlar', ['İç püskürük kayaçlar', 'Dış püskürük kayaçlar', 'Başkalaşım kayaçları'], 'Suda çözünmüş silisin (SiO2) çökelmesiyle oluşan çakmaktaşı ve opal gibi kayaçlar silisli kimyasal tortul kayaçlar grubundadır.'),
  ('Pamuk tarımı için çok elverişli olan, Büyük Menderes, Küçük Menderes ve Gediz nehirlerinin taşıyıp biriktirdiği toprak tipi hangisidir?', 'Alüvyal topraklar', ['Tundra toprakları', 'Podzol topraklar', 'Laterit topraklar'], 'Ege Bölgesi\'ndeki çöküntü (graben) ovalarında nehirlerin taşıdığı derin ve verimli alüvyal topraklar pamuk, incir, üzüm ve sebze tarımına çok uygundur.'),
  ('Kayaların gündüz ısınıp genleşmesi, gece ise soğuyup büzülmesi sonucunda ufalanarak kum ve çakıl boyutuna ayrılması nerede en belirgindir?', 'Orta kuşak ve dönence çöllerinde', ['Sürekli yağışlı ekvatoral ormanlarda', 'Okyanusal iklimin görüldüğü kıyılarda', 'Derin okyanus ve deniz tabanlarında'], 'Gündüz-gece sıcaklık farkının 40-50 dereceyi bulduğu nemden yoksun çöllerde termal genleşme ve büzülmeye bağlı fiziksel çözülme en şiddetlidir.'),
  ('Kaya çatlaklarına dolan suyun sıfır derecenin altında donarak hacminin genişlemesi ve kayayı çatlatarak parçalaması hangi çözülme türüdür?', 'Fiziksel (mekanik) çözülme', ['Kimyasal (oksitlenme) çözülmesi', 'Organik tortullanma süreci', 'Derinlik metamorfizması'], 'Su donduğunda hacmi yaklaşık %9 oranında artar; çatlaklarda donup çözülen suyun kayaları kama gibi parçalaması (don çatlatması) fiziksel bir çözülmedir.'),
  ('Kaya tuzu (halit) yataklarının Türkiye\'de Çankırı, Kırşehir, Yozgat, Sivas ve Iğdır çevresinde bulunması hangi jeolojik birikimle ilgilidir?', 'Kimyasal tortullanma', ['Volkanik lav akıntısı', 'Buzul aşındırması', 'Kömürleşme süreci'], 'Tersiyer\'deki sığ deniz kollarının ve kapalı göllerin kurak dönemlerde buharlaşmasıyla İç ve Doğu Anadolu\'da zengin kimyasal tortul kaya tuzu yatakları oluşmuştur.'),
  ('Toprakta yaşayan solucan, karınca ve köstebek gibi canlıların toprak oluşumuna ve verimine en önemli fiziksel katkısı nedir?', 'Toprağı havalandırmak, karıştırmak ve suyun sızmasını kolaylaştırmak', ['Ana kayayı yüksek sıcaklıkla eriterek mermere dönüştürmek', 'Topraktaki tüm suyu tüketerek çölleşmeye neden olmak', 'Yağış miktarını artırarak iklim tipini tamamen değiştirmek'], 'Toprak içi canlıları açtıkları boşluklarla toprağın havalanmasını, yağmur suyunun alt katmanlara sızmasını ve organik maddenin karışmasını sağlar.'),
  ('Ayçiçeği üretiminde Türkiye\'de ilk sırada yer alan Trakya\'da, eski göl tabanlarındaki killi depolar üzerinde oluşan dönen topraklara yöre halkı ne ad verir?', 'Karakepir (veya taş doğuran)', ['Çorak (tuzlu bataklık)', 'Kırmızı Akdeniz toprağı', 'Sarı rüzgar toprağı'], 'Trakya\'da koyu renkli killi vertisollere "karakepir", Anadolu\'nun bazı yörelerinde ise alt katmandaki taşları yüzeye ittiği için "taş doğuran" denir.'),
  ('İğne yapraklı ormanların (tayga/boreal) yayılış gösterdiği Rusya, Kanada ve İskandinavya\'da en geniş alanı kaplayan zonal toprak tipi hangisidir?', 'Podzol topraklar', ['Laterit topraklar', 'Terra rossa topraklar', 'Kırmızımsı çöl toprakları'], 'Sert karasal ve soğuk nemli iklimin iğne yapraklı tayga ormanları kuşağında tipik olarak kül renkli, yıkanmış podzol topraklar gelişir.'),
  ('Toprak oluşumunu etkileyen aşağıdaki faktörlerden hangisi diğerlerinden farklı olarak "pasif" faktörler arasında değerlendirilir?', 'Ana kaya ve yer şekilleri (topoğrafya)', ['İklim (sıcaklık ve yağış elemanları)', 'Canlılar (bitki örtüsü ve mikroorganizmalar)', 'Bakteri ve mantarların ayrıştırıcı etkisi'], 'Toprak oluşumunda iklim ve canlılar "aktif" faktörler iken; ana kaya, yer şekilleri (eğim, bakı, yükselti) ve zaman "pasif" faktörler olarak kabul edilir.'),
  ('Demir, alüminyum ve kilin bol yağışla aşırı yıkanması sonucu kiremit kırmızısı renk alan ve Brezilya ile Kongo Havzası\'nda yaygın olan toprak hangisidir?', 'Laterit', ['Çernozyom', 'Sierozem', 'Rendzina'], 'Amazon (Brezilya), Kongo Havzası ve Endonezya adaları gibi Ekvatoral iklim bölgelerinin karakteristik yerli toprağı kırmızı renkli laterittir.'),
  ('Suda kolay çözünebilen kireç taşı, alçı taşı ve kaya tuzu gibi kayaçların üzerinde oluşan en küçük karstik aşındırma şekline ne ad verilir?', 'Lapya', ['Dolin', 'Uvala çanağı', 'Polye ovası'], 'Lapya, kimyasal çözünme sonucunda kayaç yüzeylerinde oluşan ve genişliği birkaç santimetre ile birkaç metre arasında değişen en küçük karstik aşındırma oluklarıdır.'),
  ('Birden fazla lapyanın birleşip genişlemesiyle meydana gelen, tava veya huni biçimindeki sığ erime çukurlarına ne ad verilir?', 'Dolin', ['Mağara boşluğu', 'Traverten basamağı', 'Yardang sırtı'], 'Dolin (koyak), lapyaların zamanla genişleyip birleşmesiyle oluşan ve çapları birkaç on metreden birkaç yüz metreye ulaşabilen erime çukurlarıdır.'),
  ('Komşu dolinlerin kenarlarının eriyerek birleşmesi sonucunda oluşan daha geniş ve düzensiz karstik çanaklara ne ad verilir?', 'Uvala', ['Şahitkaya tepesi', 'Barkan kumulu', 'Hamada düzlüğü'], 'Uvala, birbirine yakın birden fazla dolinin arasındaki bölmelerin kimyasal çözünmeyle ortadan kalkması sonucu oluşan orta büyüklükteki karstik çukurluklardır.'),
  ('Tabanı alüvyonlarla kaplı olan, tarıma elverişli geniş karstik ovalara ne ad verilir?', 'Polye', ['Tafoni kovuğu', 'Obruk çukuru', 'Düden kuyusu'], 'Polye (gölova), uvalaların genişlemesi ve tektonik hatların da etkisiyle oluşan en geniş karstik aşınım şeklidir; tabanında verimli tarım arazileri bulunur.'),
  ('Yer altı mağaralarının tavanlarının çökmesi sonucunda oluşan derin, dik yamaçlı baca veya kuyu görünümlü karstik şekillere ne ad verilir?', 'Obruk', ['Lös birikintisi', 'Kıyı kumulu', 'Mantarkaya sütunu'], 'Obruk, yer altındaki mağara ve galerilerin tavan kısmının ağırlığı taşıyamayarak çökmesiyle meydana gelen derin karstik kuyulardır.'),
  ('Yüzey sularını yer altına indiren veya yer altı sularını tekrar yüzeye çıkaran doğal karstik kanallara ne ad verilir?', 'Düden', ['Uvala çukuru', 'Polye tabanı', 'Barkan hilali'], 'Düden (suyutan veya suçıkan), polye ve uvala gibi kapalı karstik havzalardaki suları yer altına aktaran doğal erime kanallarıdır.'),
  ('Kalsiyum bikarbonatça zengin yer altı sularının yüzeye çıktığı yerlerde karbondioksidin uçması ve kirecin çökelmesiyle oluşan basamaklı birikim şekli hangisidir?', 'Traverten', ['Şahitkaya', 'Polye ovası', 'Dolin çanağı'], 'Traverten, sıcak ya da soğuk karstik kaynak sularının yüzeye çıktığı yamaçlarda kalsiyum karbonatın çökelmesiyle oluşan beyaz veya sarımsı basamaklı birikim şeklidir.'),
  ('Mağara tavanlarından damlayan kireçli suların tavanda birikmesiyle aşağı doğru uzanan karstik birikim şekline ne ad verilir?', 'Sarkıt', ['Dikit sütunu', 'Traverten taraçası', 'Obruk bacası'], 'Sarkıt, mağara tavanındaki çatlaklardan sızan kalsiyum karbonatlı suların damlarken tavanda kireç biriktirmesiyle oluşan sarkık şekillerdir.'),
  ('Mağara tavanından damlayan kireçli suların mağara tabanında üst üste çökelmesiyle yukarı doğru yükselen şekle ne ad verilir?', 'Dikit', ['Sarkıt ucu', 'Lapya oluğu', 'Düden ağzı'], 'Dikit, mağara tavanından düşen su damlalarının içerdiği kalsiyum karbonatın mağara zemininde çökelip yükselmesiyle oluşur.'),
  ('Mağaralarda tavandan uzanan sarkıtlar ile tabandan yükselen dikitlerin zamanla birleşmesi sonucunda oluşan karstik şekil hangisidir?', 'Sütun', ['Uvala çanağı', 'Tafoni oyuğu', 'Kör vadi'], 'Sarkıt ve dikitlerin binlerce yıl süren büyüme sonucunda uç uca kavuşup kaynaşmasıyla mağara sütunları meydana gelir.'),
  ('Türkiye\'de karstik yer şekillerinin en yaygın ve gelişmiş olarak görüldüğü coğrafi bölge aşağıdakilerden hangisidir?', 'Akdeniz Bölgesi', ['Doğu Anadolu Bölgesi', 'Karadeniz Bölgesi', 'Marmara Bölgesi'], 'Toros Dağları kuşağında kalın ve saf kalker (kireç taşı) tabakalarının geniş yer kaplaması nedeniyle Türkiye\'de karstik şekiller en çok Akdeniz Bölgesi\'nde görülür.'),
  ('Denizli il sınırları içinde yer alan ve UNESCO Dünya Mirası Listesi\'nde bulunan Pamukkale, aşağıdaki yer şekillerinden hangisinin dünyaca ünlü örneğidir?', 'Traverten', ['Obruk gölü', 'Polye ovası', 'Barkan kumulu'], 'Pamukkale, termal karstik kaynak sularının yamaç boyunca kalsiyum karbonat çökeltmesiyle oluşmuş görkemli bir traverten alanıdır.'),
  ('Mersin\'in Silifke ilçesi yakınlarında bulunan Cennet ve Cehennem çukurları aşağıdaki karstik şekillerden hangisine örnektir?', 'Obruk', ['Polye ovası', 'Traverten basamağı', 'Lapya yüzeyi'], 'Cennet ve Cehennem çökükleri, yer altı mağara tavanlarının çökmesiyle oluşmuş tipik obruk örnekleridir.'),
  ('Antalya, Burdur, Isparta ve Denizli çevresinde yer alan Elmalı, Kestel, Acıpayam ve Korkuteli ovaları oluşum bakımından hangi gruba girer?', 'Karstik polye ovaları', ['Tektonik çöküntü ovaları', 'Akarsu delta ovaları', 'Volkanik lav düzlükleri'], 'Elmalı, Kestel, Acıpayam, Tefenni, Korkuteli ve Castellorizo ardındaki Göller Yöresi ovaları "TAKKE" kodlamasıyla da bilinen başlıca karstik polye ovalarıdır.'),
  ('Sivas, Çankırı ve Erzincan çevresinde görülen karstik yer şekilleri, Akdeniz Bölgesi\'ndekilerden farklı olarak ağırlıklı biçimde hangi kayaç üzerinde gelişmiştir?', 'Jips (alçı taşı)', ['Kalker (kireç taşı)', 'Granit kütleleri', 'Bazalt akıntıları'], 'Sivas, Çankırı ve Erzincan çevresinde yaygın olan karstik erime çukurları ve mağaralar suda çok hızlı çözünen jips (alçı taşı) tabakaları üzerinde gelişmiştir.'),
  ('Kimyasal çözünme süreçlerinin hızlanması ve iri karstik şekillerin oluşabilmesi için kayaç özelliğinin yanı sıra aşağıdaki koşullardan hangisi gereklidir?', 'Yeterli su ve nem varlığı', ['Şiddetli rüzgâr erozyonu', 'Kalıcı buzul örtüsü', 'Aktif volkanik faaliyetler'], 'Karstlaşma esas olarak suyun içindeki karbondioksitle birleşip kayacı kimyasal olarak çözmesine dayandığından yeterli yağış ve su dolaşımı şarttır.'),
  ('Bir akarsuyun karstik arazide ilerlerken bir düden aracılığıyla yer altına dalması sonucunda yüzeyde aniden sona eren vadilere ne ad verilir?', 'Kör vadi', ['Boğaz vadi', 'Çentik vadi', 'Asılı vadi'], 'Kör vadi (çıkmaz vadi), akarsuyun bir suyutan (düden) ağzından yer altına girmesiyle akışının yüzeyde kesildiği ve önünde dik bir yamacın belirdiği karstik vadidir.'),
  ('Türkiye\'de Konya Havzası\'nda yer altı sularının aşırı çekilmesiyle oluşumu hızlanan derin çöküntü çukurları hangi karstik şekildir?', 'Obruk', ['Traverten', 'Şahitkaya', 'Yardang'], 'Konya ve Karapınar çevresinde yer altı su seviyesinin düşmesiyle mağara tavanlarındaki hidrostatik destek azalmakta ve obruk oluşumu hızlanmaktadır.'),
  ('Aşağıdaki kayaç türlerinden hangisi karstik aşındırma ve biriktirme şekillerinin oluşmasına elverişli değildir?', 'Andezit', ['Kalker', 'Jips', 'Kaya tuzu'], 'Kalker, jips, dolomit ve kaya tuzu suda kolay çözünen kimyasal tortul kayaçlarken; andezit dış püskürük (volkanik) bir kayaç olup karstlaşmaya uygun değildir.'),
  ('Karstik arazilerde kireç taşının çözünmesi sonrasında geriye kalan demir oksitçe zengin, kızıl renkli kil-toprak örtüsüne ne ad verilir?', 'Terra rossa', ['Çernozyom', 'Podzol toprağı', 'Lös birikimi'], 'Akdeniz iklim kuşağındaki kalkerli arazilerde karbonatların yıkanması ve demir bileşiklerinin oksitlenmesiyle kızıl renkli terra rossa toprakları oluşur.'),
  ('Alanya\'daki Damlataş, Burdur\'daki İnsuyu ve Antalya\'daki Karain oluşum kökeni bakımından hangi yer şekli grubuna girer?', 'Karstik mağara', ['Rüzgâr kovuğu', 'Buzul sirki', 'Dalga falezleri'], 'Damlataş, İnsuyu, Karain, Dim ve Ballıca Türkiye\'nin kireç taşı içinde gelişmiş başlıca doğal karstik mağaralarıdır.'),
  ('Karstik aşındırma şekillerinin en küçüğünden en büyüğüne doğru sıralanışı aşağıdakilerden hangisinde doğru verilmiştir?', 'Lapya - Dolin - Uvala - Polye', ['Dolin - Lapya - Polye - Uvala', 'Polye - Uvala - Dolin - Lapya', 'Lapya - Uvala - Dolin - Polye'], 'Karstik erime çukurları zamanla birleşip genişleyerek sırasıyla lapya, dolin, uvala ve en son geniş tarım ovaları olan polyeleri oluşturur.'),
  ('Rüzgârın aşındırma ve biriktirme faaliyetlerinin yeryüzünde en etkili olduğu iklim bölgeleri aşağıdakilerden hangisidir?', 'Kurak ve yarı kurak bölgeler', ['Sürekli yağışlı ekvatoral bölgeler', 'Ilıman okyanusal kıyı bölgeleri', 'Tundra ve kutup altı bölgeleri'], 'Yağışın az, bitki örtüsünün cılız, fiziksel ufalanmanın ise şiddetli olduğu kurak ve yarı kurak (çöl ve step) bölgelerde rüzgâr en etkili dış kuvvetlerden biridir.'),
  ('Farklı dirençteki yatay tabakalardan oluşan arazilerde rüzgârın aşındırması sonucu dirençli kısımların masa-tepe gibi ayakta kalmasıyla oluşan şekil hangisidir?', 'Şahitkaya', ['Dolin çukuru', 'Obruk kuyusu', 'Kıyı kordonu'], 'Şahitkaya, yatay uzanışlı tortul tabakalarda yumuşak kısımların rüzgârla aşınıp taşınması, sert kısımların ise eski yüzeyin tanığı gibi yüksekte kalmasıyla oluşur.'),
  ('Kurak bölgelerde rüzgârın hakim esiş yönüne paralel olarak uzanan, birbirinden oluklarla ayrılmış keskin sırtlara ne ad verilir?', 'Yardang', ['Barkan', 'Uvala', 'Sarkıt'], 'Yardang, farklı dirençteki kayaçların bulunduğu kurak sahalarda rüzgârın gevşek kısımları oyup taşımasıyla rüzgâr yönüne paralel uzanan aerodinamik sırt ve oluklardır.'),
  ('Kayaçların yüzeyinde fiziksel-kimyasal ayrışma ve rüzgârın gevşek kırıntıları süpürmesiyle oluşan kuş yuvası veya bal peteği görünümlü oyuklara ne ad verilir?', 'Tafoni', ['Polye', 'Lös', 'Düden'], 'Tafoni, kurak ve yarı kurak ya da tuzlu kıyı bölgelerinde kayaç yüzeylerinde nemlenme-buharlaşma ve rüzgâr süpürmesiyle oluşan kovuk ve oyuklardır.'),
  ('Çöllerde ince kum ve toz boyutundaki kırıntıların rüzgâr tarafından tamamen süpürülmesi sonucunda geriye kalan taşlı ve kayalık çöl yüzeylerine ne ad verilir?', 'Hamada (çöl kaldırımı)', ['Barkan (hilal kumul)', 'Lös platosu', 'Polye tabanı'], 'Hamada (kaya çölü) ve reg (çöl kaldırımı), rüzgârın deflasyon (süpürme) faaliyeti sonucunda ince malzemenin taşınıp iri taş ve kayaların geride kaldığı çöl düzlükleridir.'),
  ('Çöllerde rüzgârın taşıdığı kumları biriktirmesiyle oluşan hilal (yarım ay) biçimindeki hareketli kumul tepelerine ne ad verilir?', 'Barkan', ['Şahitkaya', 'Yardang', 'Obruk'], 'Barkan, hakim rüzgâr yönünün belirgin olduğu kurak alanlarda kumların birikmesiyle oluşan ve uçları rüzgârın estiği yönün ilerisine doğru uzanan hilal şekilli kumullardır.'),
  ('Rüzgârın kurak sahalardan havalandırıp uzak mesafelere taşıyarak biriktirdiği ince toz ve mil boyutundaki sarımsı tortul depolara ne ad verilir?', 'Lös', ['Hamada', 'Lapya', 'Tafoni'], 'Lös, rüzgârların çöllerden veya buzul çevresi alanlardan taşıdığı çok ince toz ve silt unsurlarının yarı kurak bozkır çevrelerinde yığılmasıyla oluşan verimli depolardır.'),
  ('Rüzgârın hızının azaldığı veya bir engele çarptığı yerlerde kum tanelerinin üst üste yığılmasıyla oluşan tepelere genel olarak ne ad verilir?', 'Kumul', ['Mağara', 'Dolin', 'Falez'], 'Kumullar, çöl içlerinde, göl çevrelerinde ve deniz kıyılarında rüzgârın taşıdığı kum boyutundaki malzemeyi biriktirmesiyle meydana gelen yığınlardır.'),
  ('Türkiye\'de rüzgâr aşındırma ve biriktirme şekillerinin en belirgin olarak görüldüğü coğrafi bölgeler aşağıdakilerden hangisinde birlikte verilmiştir?', 'İç Anadolu ve Güneydoğu Anadolu', ['Karadeniz ve Marmara', 'Doğu Anadolu ve Karadeniz', 'Ege ve Marmara'], 'Yıllık yağış miktarının az, yaz kuraklığının belirgin ve doğal bitki örtüsünün cılız olduğu İç Anadolu (özellikle Konya-Karapınar) ile Güneydoğu Anadolu\'da rüzgâr şekilleri yaygındır.'),
  ('Tafoni oluşumunda rüzgârın aşındırma ve süpürme etkisinin yanı sıra kayaç gözeneklerinde kristalleşerek ufalanmayı hızlandıran madde hangisidir?', 'Tuz kristalleri', ['Bitki kökleri', 'Mercan iskeletleri', 'Petrol sızıntıları'], 'Nemle kayaç gözeneklerine giren sular buharlaştığında tuz kristalleri büyüyerek kayaç dokusunu çatlatır; rüzgâr ise ufalanan bu kırıntıları süpürerek tafonileri genişletir.'),
  ('Çöllerde ince kumların taşınmasıyla geriye kalan çakıl örtülü düzlüklere Kuzey Afrika (Sahra) terminolojisinde ne ad verilir?', 'Reg (serir)', ['Erg (kum çölü)', 'Polye (gölova)', 'Voklüz (suçıkan)'], 'Çöllerde kayalık ana kaya yüzeylerine hamada, çakıl örtülü çöl kaldırımı düzlüklerine reg (veya serir), geniş kumul denizlerine ise erg adı verilir.'),
  ('Geniş kumul tepeleri ve barkanlarla kaplı olan kum çöllerine verilen coğrafi terim aşağıdakilerden hangisidir?', 'Erg', ['Hamada', 'Uvala', 'Lapya'], 'Erg, Sahra ve Arabistan çöllerinde olduğu gibi rüzgârın taşıdığı kumların geniş alanlarda birikmesiyle oluşan büyük kum çölü sahalarıdır.'),
  ('Aşağıdaki yer şekillerinden hangisi rüzgârın biriktirme faaliyeti sonucunda oluşmuştur?', 'Lös', ['Tafoni', 'Yardang', 'Şahitkaya'], 'Tafoni, yardang, şahitkaya, mantarkaya ve hamada rüzgâr aşındırma şekilleriyken; lös, kumul ve barkan rüzgâr biriktirme şekilleridir.'),
  ('Aşağıdaki yer şekillerinden hangisi rüzgârın aşındırma faaliyeti sonucunda meydana gelmez?', 'Barkan', ['Mantarkaya', 'Yardang', 'Hamada'], 'Mantarkaya, yardang ve hamada rüzgârın aşındırma (korrazyon ve deflasyon) şekilleridir; barkan ise hilal biçimli bir rüzgâr biriktirme şeklidir.'),
  ('Aşağıdaki yer şekillerinden hangisi karstik biriktirme süreçleri sonucunda oluşur?', 'Dikit', ['Dolin', 'Obruk', 'Uvala'], 'Dolin, uvala ve obruk kireç taşının çözünmesi veya mağara çökmesiyle oluşan karstik aşınım şekilleridir; dikit ise mağara tabanında oluşan birikim şeklidir.'),
  ('Burdur Gölü yakınlarında yer alan ve Türkiye\'de turizme açılan ilk mağara olma özelliğini taşıyan karstik mağara hangisidir?', 'İnsuyu Mağarası', ['Ballıca Mağarası', 'Dupnisa Mağarası', 'Karaca Mağarası'], 'Burdur-Antalya kara yolu üzerindeki İnsuyu Mağarası, içinde küçük karstik göller barındıran ve 1965 yılında Türkiye\'de turizme açılan ilk mağaradır.'),
  ('Gümüşhane\'nin Torul ilçesi sınırlarında bulunan, damlataş havuzları ve renkli sarkıtlarıyla tanınan karstik mağara aşağıdakilerden hangisidir?', 'Karaca Mağarası', ['Damlataş Mağarası', 'Dim Mağarası', 'Yarımburgaz Mağarası'], 'Gümüşhane Cebeli köyü yakınlarındaki Karaca Mağarası, dolomitik kireç taşı içinde gelişmiş zengin sarkıt, dikit ve traverten havuzlarıyla ünlüdür.'),
  ('Antalya\'nın batısında Likya antik kentlerinden Xanthos\'un denize açıldığı kıyıda yer alan Türkiye\'nin en uzun ve geniş kıyı kumulu sahası hangisidir?', 'Patara Kumulları', ['Bafra Kıyı Kordonu', 'Kapıdağ Tombolosu', 'Büyükçekmece Lagünü'], 'Eşen Çayı\'nın taşıdığı kumların dalgalar ve batı rüzgârlarıyla kıyı gerisine yığılmasıyla oluşan Patara Kumulları Türkiye\'nin en görkemli kıyı kumul alanıdır.'),
  ('Mersin\'in Silifke ilçesinde Cennet ve Cehennem obruklarının hemen yakınında bulunan, sarkıt ve dikitleriyle ünlü karstik mağara hangisidir?', 'Astım (Dilek) Mağarası', ['Tuz Mağarası', 'Kaklık Mağarası', 'Buzluk Mağarası'], 'Silifke Narlıkuyu yakınlarındaki Astım Mağarası, yüksek nem oranına sahip havası ve dev sarkıt-dikit oluşumlarıyla bilinen bir karstik mağaradır.'),
  ('Kurak bölgelerde bitki örtüsünün gür olmaması rüzgârın şekillendirici etkisini nasıl değiştirir?', 'Toprak yüzeyini koruyan engel bulunmadığı için rüzgârın aşındırma ve taşıma gücünü artırır', ['Rüzgârın hızını tamamen durdurarak kumların yerinde kayalaşmasına yol açar', 'Havadaki nem oranını yükselterek kimyasal çözünmeyi ve lapya oluşumunu başlatır', 'Barkan tepelerinin kısa sürede polye ovalarına dönüşmesine neden olur'], 'Bitki örtüsü kökleriyle toprağı tutar ve gövdesiyle rüzgâr hızını keser; bitki örtüsünden yoksun kurak arazilerde rüzgâr doğrudan zemine temas ederek güçlü erozyon yapar.'),
  ('Batı Toroslar ve Göller Yöresi\'nde yer alan Tefenni, Acıpayam, Korkuteli, Kestel ve Elmalı ovalarının ortak oluşum özelliği nedir?', 'Karstik erime ve tektonik etkilerle oluşmuş polye ovaları olmaları', ['Rüzgârın taşıdığı löslerin yığılmasıyla oluşmuş çöl düzlükleri olmaları', 'Akarsuların deniz kıyısında biriktirdiği delta ovaları olmaları', 'Buzul aşındırmasıyla açılmış yüksek dağ sirkleri olmaları'], 'Tefenni, Acıpayam, Korkuteli, Kestel ve Elmalı ("TAKKE" ovaları) Batı Toros kuşağının en tanınmış karstik polye ovalarıdır.'),
  ('Dünya haritası üzerinde Büyük Sahra, Arabistan Yarımadası, Orta Asya (Taklamakan-Gobi) ve Orta Avustralya işaretlendiğinde hangi dış kuvvetin etkili olduğu alanlar gösterilmiş olur?', 'Rüzgârların', ['Buzulların', 'Gelgit akıntılarının', 'Mercan resiflerinin'], 'Büyük Sahra, Arabistan, Orta Asya ve Orta Avustralya dünyanın başlıca dönence ve orta kuşak çölleri olup rüzgâr şekillerinin en yoğun görüldüğü sahalardır.'),
  ('Rüzgârın taşıdığı kumların kayalara çarparak onların keskin yüzeyler kazanmasına neden olduğu üç veya çok yüzeyli çöl çakıllarına ne ad verilir?', 'Façaetalı taş', ['Traverten konisi', 'Sarkıt dikiti', 'Dolin çakılı'], 'Rüzgârın kum püskürterek (korrazyonla) çöl zeminindeki sabit çakılların rüzgâra bakan yüzlerini düzleştirip parlatmasıyla façaetalı taşlar (rüzgâr taşları) oluşur.'),
  ('İstanbul\'un Başakşehir ilçesi sınırlarında Altınşehir yakınlarında bulunan ve Paleolitik döneme ait izler taşıyan karstik mağara hangisidir?', 'Yarımburgaz Mağarası', ['Damlataş Mağarası', 'İnsuyu Mağarası', 'Ballıca Mağarası'], 'Eosen yaşlı kireç taşları içinde gelişmiş olan Yarımburgaz Mağarası, Marmara Bölgesi\'ndeki önemli karstik mağaralardan biridir.'),
  ('Karstik bir bölgede yüzeyde lapya, dolin ve uvalaların yaygın olması o bölgenin kayaç yapısı hakkında öncelikle neyi gösterir?', 'Arazide suda kolay çözünebilen kimyasal tortul kayaçların geniş yer kapladığını', ['Arazinin tamamen genç bazalt ve granit lavlarıyla örtülü olduğunu', 'Bölgede rüzgâr biriktirmesiyle kalın kumul tepelerinin oluştuğunu', 'Zeminin geçirimsiz kil taşı ve taş kömürü damarlarından meydana geldiğini'], 'Lapya, dolin ve uvala gibi karstik erime şekilleri yalnızca kalker, jips, dolomit ve kaya tuzu gibi suda çözünebilen kimyasal tortul kayaçlar üzerinde gelişir.'),
  ('Çöl içlerinde deflasyon çukurlarının yer altı su seviyesine kadar derinleşmesiyle suyun yüzeye çıktığı, tarım ve yerleşmeye elverişli yeşil alanlara ne ad verilir?', 'Vaha', ['Polye', 'Obruk', 'Hamada'], 'Vaha, çöllerde rüzgârın açtığı derin deflasyon çanaklarında veya fay kaynakları boyunca yer altı suyunun yüzeye yaklaşmasıyla oluşan sulak ve bitkili yaşam alanlarıdır.'),
  ('Kireç taşının başkalaşıma (metamorfizmaya) uğramasıyla oluşan mermer kütleleri üzerinde yağışlı bölgelerde küçük çaplı erime oluklarının görülmesi neyin sonucudur?', 'Mermerin de temel bileşeninin kalsiyum karbonat olması nedeniyle kısmen karstlaşabilmesinin', ['Mermerin rüzgârla taşınan lös tozlarının sıkışmasıyla oluşmasının', 'Mermer yüzeyinde yalnızca volkanik asit yağmurlarının etkili olmasının', 'Mermerin suda kaya tuzundan daha hızlı eriyen bir kayaç olmasının'], 'Mermer, kalkerin yüksek sıcaklık ve basınç altında kristalleşmesiyle oluşur; gözenekliliği azalsa da kimyasal bileşimi CaCO3 olduğu için Dupnisa ve Muğla çevresindeki gibi karstik şekiller barındırabilir.'),
  ('Mağara tavanlarının çökmesiyle oluşan obruklar ile kireç taşının yüzeyden erimesiyle başlayan dolinler arasındaki temel oluşum farkı nedir?', 'Dolinler yüzeyden itibaren kimyasal erimeyle sığ çanaklar halinde gelişirken, obruklar yer altı boşluğunun tavan çökmesiyle dik ve derin açılır', ['Dolinler rüzgâr biriktirmesiyle oluşurken, obruklar rüzgâr aşındırmasıyla oluşur', 'Dolinler yalnızca jips kayacında, obruklar ise yalnızca granit kayacında meydana gelir', 'Dolinlerin tabanında her zaman sıcak su gayzeri bulunurken, obruklar tamamen kumla doludur'], 'Erime dolinleri yüzeysel kimyasal çözünmeyle yavaşça genişleyen huni/tava biçimli çukurlardır; obruklar ise alttaki mağara tavanının mekanik olarak çökmesiyle aniden beliren derin bacalardır.'),
  ('Rüzgârın aşındırma yaparken kayaların yumuşak kısımlarını oyup sert kısımlarını bırakması olayına genel olarak ne ad verilir?', 'Seçici (diferansiyel) aşındırma', ['Kimyasal çökelme', 'Karstik biriktirme', 'Tektonik kıvrılma'], 'Mantarkaya, şahitkaya, yardang ve tafoni gibi rüzgâr aşınım şekillerinin belirginleşmesinde kayaç tabakalarının veya minerallerinin farklı direnç göstermesi (seçici aşındırma) çok önemlidir.'),
  ('Yüksek dağ zirvelerinde buzulların zemini oyarak oluşturduğu çanak şeklindeki aşınım çukurluklarına ne ad verilir?', 'Sirk', ['Buzul vadisi', 'Hörgüçkaya', 'Sander düzlüğü'], 'Sirkler buzulların dağ yamaçlarında veya zirve yakınlarında oluşturduğu koltuk biçimli aşınım çanaklarıdır.'),
  ('Buzulların aşındırarak taşıdığı irili ufaklı taş, çakıl ve kum yığınlarının erime bölgesinde birikmesiyle oluşan depolara ne denir?', 'Moren', ['Drumlin', 'Barkan', 'Tombolo'], 'Buzultaş olarak da bilinen morenler, boylanmamış ve köşeli malzemelerden oluşan temel buzul birikim şeklidir.'),
  ('Bir adanın kıyı oku yardımıyla anakaraya bağlanması sonucunda meydana gelen yarımada şekline coğrafyada ne ad verilir?', 'Tombolo', ['Lagün', 'Falez', 'Haliç'], 'Saplı ada olarak da adlandırılan tombolo, dalga ve akıntıların kıyı ile ada arasını kumlarla doldurmasıyla oluşur.'),
  ('Dalgaların dik kıyıları alt kısımlarından aşındırıp çökertmesiyle oluşan sarp kıyı uçurumlarına ne ad verilir?', 'Falez', ['Kıyı oku', 'Kıyı kordonu', 'Sirk çanağı'], 'Yalıyar olarak da bilinen falezler, dağların kıyıya paralel ve yakın uzandığı dik kıyılarda yaygındır.'),
  ('Türkiye\'de Marmara Denizi kıyısında yer alan Kapıdağ Yarımadası hangi kıyı birikim şeklinin en tipik örneklerinden biridir?', 'Tombolo', ['Lagün gölü', 'Kıyı taraçası', 'Dalmaçya kıyısı'], 'Kapıdağ Yarımadası eski bir adanın kıyı oklarıyla anakaraya bağlanması sonucu oluşmuş bir tombolodur.'),
  ('Koy veya körfez önlerinin kıyı kordonlarıyla tamamen kapanması sonucu denizden ayrılan kıyı set göllerine ne ad verilir?', 'Lagün', ['Sirk gölü', 'Haliç', 'Fiyort'], 'Deniz kulağı olarak da bilinen lagünler sığ kıyılarda dalga biriktirmesiyle oluşur.'),
  ('İstanbul\'daki Büyükçekmece, Küçükçekmece ve Terkos gölleri oluşum bakımından hangi kıyı şekli grubuna girer?', 'Lagün', ['Tombolo', 'Haliç', 'Fiyort'], 'Bu üç göl koy ağızlarının kıyı kordonlarıyla kapanması sonucu oluşmuş lagün (kıyı set) gölleridir.'),
  ('Buzulların eski akarsu vadilerini aşındırarak enine kesitini hangi harf biçimine dönüştürdüğü görülür?', 'U', ['V', 'S', 'M'], 'Buzul vadileri tabanları geniş ve yamaçları dik olan U profilli tekne vadilerdir.'),
  ('Buzulların anakayayı aşındırmasıyla oluşan, bir yamacı az eğimli diğer yamacı dik, tümsekli ve cilalı kayalıklara ne ad verilir?', 'Hörgüçkaya', ['Şahitkaya', 'Mantarkaya', 'Kırgıbayır'], 'Hörgüçkayalar buzul törpülemesi ve koparması sonucunda oluşan asimetrik profilli aşınım kayalarıdır.'),
  ('Buzulların erimesiyle ortaya çıkan akarsuların buzul önünde biriktirdiği geniş çakıl ve kum ovalarına ne ad verilir?', 'Sander düzlüğü', ['Delta ovası', 'Taban seviyesi ovası', 'Dağ eteği ovası'], 'Sander düzlükleri buzul cephesinden çıkan erime sularının taşıdığı malzemelerin yayılmasıyla oluşur.'),
  ('Buzul tabanında morenlerin buz hareketi yönünde uzanacak şekilde balina sırtına benzer tepeler oluşturmasıyla meydana gelen şekil hangisidir?', 'Drumlin', ['Hörgüçkaya', 'Sirk çanağı', 'Kıyı kordonu'], 'Drumlinler taban morenlerinin buzul akışı altında şekillenmesiyle oluşan kaşık veya balina sırtı biçimli tepelerdir.'),
  ('Karadeniz bölgesinde yer alan Sinop Yarımadası\'nın oluşumunda etkili olan temel dış kuvvet ve yer şekli eşleştirmesi hangisidir?', 'Dalga biriktirmesi - Tombolo', ['Dalga aşındırması - Falez', 'Akarsu biriktirmesi - Delta', 'Buzul biriktirmesi - Moren'], 'Sinop (Boztepe) adasının anakaraya bağlanmasıyla oluşan Sinop Yarımadası tipik bir tombolodur.'),
  ('Bir kıyıda falez (yalıyar) oluşumunun yaygın olması o kıyının hangi özelliğine doğrudan kanıt oluşturur?', 'Kıta sahanlığının dar ve kıyının derin olduğuna', ['Gelgit genliğinin çok yüksek olduğuna', 'Akarsuların bol alüvyon taşıdığına', 'Kıyı oklarının hızla geliştiğine'], 'Falezler sığ kıyılarda değil, dağların hemen kıyıdan yükseldiği derin ve dik kıyılarda gelişir.'),
  ('Lagün ve tombolo gibi kıyı biriktirme şekillerinin bir arada görüldüğü bir deniz kıyısı için aşağıdakilerden hangisi kesinlikle söylenebilir?', 'Kıta sahanlığı geniştir ve deniz sığdır', ['Buzul aşındırması doğrudan kıyıda etkilidir', 'Okyanusa kıyısı vardır ve gelgit güçlüdür', 'Dağlar kıyı çizgisine çok yakın ve diktir'], 'Dalga biriktirme şekillerinin oluşabilmesi için kıyının sığ, şelf alanının geniş ve gelgitin zayıf olması gerekir.'),
  ('Sirk çukurlarının buzulların erimesinden sonra suyla dolması sonucunda meydana gelen doğal göllere ne ad verilir?', 'Sirk gölü', ['Lagün gölü', 'Moren set gölü', 'Krater gölü'], 'Buzul gölü veya sirk gölü olarak bilinen bu göller Türkiye\'de yüksek dağların zirve kuşaklarında görülür.'),
  ('Dalga ve akıntıların taşıdığı kum ve çakılların kıyıdan denize doğru ok biçiminde uzanacak şekilde birikmesiyle oluşan şekle ne denir?', 'Kıyı oku', ['Falez', 'Abrazyon platformu', 'Hörgüçkaya'], 'Kıyı okları burunlardan veya kıyı girintilerinden açık denize doğru uzanan dar birikim şeritleridir.'),
  ('Türkiye kıyılarında buzul aşınım ve birikim şekillerine deniz seviyesinde rastlanmamasının temel nedeni aşağıdakilerden hangisidir?', 'Orta kuşakta yer alması', ['Üç tarafının denizlerle çevrili olması', 'Yükseltisinin batıdan doğuya artması', 'Genç oluşumlu arazi yapısına sahip olması'], 'Türkiye orta kuşakta bulunduğu için Kuaterner buzullaşmasında bile kalıcı buzullar deniz seviyesine inmemiştir.'),
  ('Dalgaların falezleri geriletmesi sonucunda falez önünde deniz seviyesine yakın olarak oluşan düzlüklere ne ad verilir?', 'Abrazyon platformu', ['Sander düzlüğü', 'Kıyı kordonu', 'Buzul vadisi'], 'Aşınım düzlüğü olarak da bilinen abrazyon platformu, gerileyen falezin tabanında gelişen sığ kaya düzlüğüdür.'),
  ('Bir koyun önünü kapatacak biçimde bir uçtan diğer uca uzanan genişlemiş kıyı oklarına ne ad verilir?', 'Kıyı kordonu', ['Tombolo', 'Falez', 'Drumlin'], 'Kıyı oklarının büyüyüp koy önünü boydan boya katetmesiyle kıyı kordonları meydana gelir.'),
  ('Cilo, Kaçkar ve Aladağlar gibi yüksek kütlelerin zirvelerinde sirk göllerine rastlanması neyin göstergesidir?', 'Geçmiş jeolojik dönemlerde buzul aşındırmasına uğradıklarının', ['Volkanik patlamalarla çukurlukların oluştuğunun', 'Kireçtaşı tabakalarının eriyerek çöktüğünün', 'Rüzgar aşındırmasının şiddetli olduğunun'], 'Yüksek dağlardaki sirk gölleri Pleistocene dönemindeki ve güncel küçük dağ buzullarının aşındırma izleridir.'),
  ('Buzul vadilerine yanlardan katılan daha küçük buzulların oluşturduğu, ana vadi tabanından yüksekte kalan vadilere ne ad verilir?', 'Asılı vadi', ['Kanyon vadi', 'Boğaz vadi', 'Çentik vadi'], 'Ana buzul vadisi yan buzullardan daha fazla derine aşındırıldığı için yan vadiler yüksekte asılı kalır.'),
  ('Aşağıdaki yer şekillerinden hangisinin oluşumunda buzulların biriktirme faaliyeti etkili olmuştur?', 'Moren tepeleri', ['Hörgüçkaya', 'Sirk çanağı', 'Tekne vadi'], 'Hörgüçkaya, sirk ve tekne vadi buzul aşınım şekilleriyken morenler buzul birikim şeklidir.'),
  ('Aşağıdaki kıyı şekillerinden hangisi dalgaların aşındırma faaliyeti sonucunda oluşmuştur?', 'Falez', ['Lagün', 'Tombolo', 'Kıyı oku'], 'Lagün, tombolo ve kıyı oku dalga biriktirme şekilleridir; falez ise dalga aşındırma şeklidir.'),
  ('Fethiye\'deki Ölüdeniz oluşum özelliği bakımından aşağıdaki kıyı şekillerinden hangisine örnektir?', 'Lagün', ['Tombolo', 'Haliç', 'Fiyort'], 'Ölüdeniz, koy ağzının kıyı kordonuyla büyük ölçüde kapanmasıyla oluşmuş durgun bir lagündür.'),
  ('Türkiye\'de güncel buzullara ve belirgin buzul yer şekillerine en yaygın olarak rastlanan dağ aşağıdakilerden hangisidir?', 'Cilo Dağı', ['Yıldız Dağları', 'Bozdağlar', 'Canik Dağları'], 'Hakkari\'deki Cilo (Buzul) Dağı yükseltisi nedeniyle Türkiye\'nin en geniş güncel vadi buzullarını barındırır.'),
  ('Dağların kıyı çizgisine paralel uzandığı yerlerde girinti ve çıkıntının az olduğu kıyı tipine ne ad verilir?', 'Boyuna kıyı', ['Enine kıyı', 'Ria kıyı', 'Haliçli kıyı'], 'Boyuna kıyılarda dağlar kıyıya paralel uzanır; koy, körfez ve doğal liman sayısı azdır.'),
  ('Dağların kıyı çizgisine dik uzandığı, koy, körfez, ada ve yarımadaların çok sayıda bulunduğu kıyı tipine ne ad verilir?', 'Enine kıyı', ['Boyuna kıyı', 'Fiyortlu kıyı', 'Watt kıyısı'], 'Enine kıyılarda çöküntü olukları koy ve körfezleri, yüksek kütleler ise burun ve yarımadaları oluşturur.'),
  ('Türkiye\'de Karadeniz ve Akdeniz kıyılarının büyük bölümünde görülen hakim kıyı tipi aşağıdakilerden hangisidir?', 'Boyuna kıyı', ['Enine kıyı', 'Dalmaçya kıyı', 'Fiyort kıyı'], 'Kuzey Anadolu Dağları ve Toroslar kıyıya paralel uzandığı için bu iki denizimizde boyuna kıyı tipi yaygındır.'),
  ('Türkiye\'de Edremit ile Kuşadası arasındaki Ege kıyılarında yaygın olarak görülen kıyı tipi hangisidir?', 'Enine kıyı', ['Boyuna kıyı', 'Haliçli kıyı', 'Watt kıyı'], 'Batı Anadolu\'da horst-graben sistemleri denize dik uzandığından Ege\'de enine kıyı tipi gelişmiştir.'),
  ('Eski akarsu vadilerinin deniz seviyesinin yükselmesi veya karanın çökmesi sonucu deniz suları altında kalmasıyla oluşan kıyı tipine ne denir?', 'Ria kıyı', ['Fiyort kıyı', 'Watt kıyı', 'Boyuna kıyı'], 'Ria kıyıları boğulmuş akarsu vadilerinden oluşur; İstanbul ve Çanakkale boğazları bunun tipik örnekleridir.'),
  ('Kıyıya paralel uzanan dağ sıraları arasındaki vadilerin deniz suları altında kalmasıyla kıyı önünde dizilmiş çok sayıda uzun adadan oluşan kıyı tipi hangisidir?', 'Dalmaçya kıyı', ['Enine kıyı', 'Haliçli kıyı', 'Limanlı kıyı'], 'Adriyatik Denizi\'ndeki Hırvatistan kıyıları ve Türkiye\'de Finike-Kaş kıyıları Dalmaçya kıyı tipine örnektir.'),
  ('Buzul vadilerinin deniz suları altında kalmasıyla oluşan, çok girintili, dar ve derin körfezli kıyı tipine ne ad verilir?', 'Fiyort kıyı', ['Ria kıyı', 'Dalmaçya kıyı', 'Boyuna kıyı'], 'Fiyortlar yüksek enlemlerdeki eski U profilli buzul vadilerinin deniz istilasına uğramasıyla oluşur; Norveç kıyıları en bilinen örnektir.'),
  ('Gelgit genliğinin yüksek olduğu okyanus kıyılarında akarsu ağızlarının gelgit akıntılarıyla aşınıp huni biçiminde genişlemesiyle oluşan kıyı tipi hangisidir?', 'Haliçli kıyı', ['Boyuna kıyı', 'Dalmaçya kıyı', 'Ria kıyı'], 'Haliç (estuar) kıyıları güçlü gelgit etkisiyle akarsu ağızlarının deniz tarafından işgal edilmesiyle oluşur.'),
  ('Gelgit genliğinin fazla olduğu alçak ve düz okyanus kıyılarında suların çekilmesiyle geniş balçıklı-kumlu deniz tabanının yüzeye çıktığı kıyı tipi hangisidir?', 'Watt kıyı', ['Fiyort kıyı', 'Dalmaçya kıyı', 'Boyuna kıyı'], 'Watt kıyıları Kuzeybatı Avrupa\'da (Hollanda, Almanya, Fransa\'nın Manş kıyıları) gelgit etkisiyle oluşan sığ çamur düzlükleridir.'),
  ('İstanbul Boğazı, Çanakkale Boğazı ve İstanbul\'daki Haliç oluşum bakımından hangi kıyı tipine örnektir?', 'Ria kıyı', ['Haliçli kıyı', 'Fiyort kıyı', 'Dalmaçya kıyı'], 'İsmi Haliç olsa da İstanbul\'daki Haliç ve boğazlarımız gelgitle değil, eski akarsu vadilerinin sular altında kalmasıyla oluşmuş ria kıyılarıdır.'),
  ('Türkiye\'de Antalya\'nın Finike ile Kaş ilçeleri arasındaki kıyılar hangi kıyı tipinin ülkemizdeki tek belirgin örneğidir?', 'Dalmaçya kıyı', ['Fiyort kıyı', 'Watt kıyı', 'Haliçli kıyı'], 'Finike-Kaş (Kekova) kıyılarında kıyıya paralel sırtların çökmesiyle kıyıya paralel uzanan adacıklar ve kanallar (Dalmaçya tipi) oluşmuştur.'),
  ('Dünya üzerinde fiyortlu kıyıların en tipik ve yaygın olarak görüldüğü ülke aşağıdakilerden hangisidir?', 'Norveç', ['Mısır', 'Brezilya', 'Endonezya'], 'İskandinav Yarımadası\'nda yer alan Norveç, yüksek enlem konumu ve dağlık yapısı nedeniyle en gelişmiş fiyort kıyılarına sahiptir.'),
  ('Türkiye\'de fiyort ve skyer tipi kıyılara doğal olarak rastlanmamasının temel nedeni aşağıdakilerden hangisidir?', 'Matematik konumu nedeniyle buzulların deniz seviyesine inmemiş olması', ['Dağların genel olarak doğu-batı yönünde uzanması', 'Kıyılarında gelgit genliğinin düşük olması', 'Akarsuların boylarının kısa ve akış hızlarının yüksek olması'], 'Fiyort ve skyer kıyıları buzul şekillerinin deniz altında kalmasıyla oluşur; orta kuşaktaki Türkiye\'de buzullar kıyıya hiç ulaşmamıştır.'),
  ('Türkiye kıyılarında gerçek anlamda haliçli ve watt tipi kıyıların gelişememesinin temel nedeni nedir?', 'İç denizlere kıyısı olduğu için gelgit genliğinin çok düşük olması', ['Kıyılarında volkanik kayaçların geniş yer kaplaması', 'Kıta sahanlığının tüm kıyılarımızda çok geniş olması', 'Yıllık sıcaklık farklarının kıyılarda az olması'], 'Haliç ve watt kıyıları okyanuslara özgü yüksek gelgit genliği gerektirir; iç denizlerde gelgit zayıftır.'),
  ('Güneybatı Anadolu\'da Menteşe yöresi (Bodrum, Marmaris, Gökova) kıyıları hangi kıyı tipine örnek gösterilir?', 'Ria kıyı', ['Watt kıyı', 'Boyuna kıyı', 'Fiyort kıyı'], 'Güneybatı Anadolu kıyıları genç tektonik çökmeler ve deniz yükselmesiyle akarsu vadilerinin boğulduğu ria tipi kıyılardır.'),
  ('Almanya\'daki Hamburg, İngiltere\'deki Londra ve Fransa\'daki Bordeaux limanlarının bulunduğu akarsu ağızları hangi kıyı tipine örnektir?', 'Haliçli kıyı', ['Dalmaçya kıyı', 'Boyuna kıyı', 'Ria kıyı'], 'Kuzey Denizi ve Atlas Okyanusu\'na dökülen Elbe, Thames ve Garonne nehirlerinin ağızlarında gelgit etkisiyle gelişmiş haliçler yer alır.'),
  ('Boyuna kıyı tipinin görüldüğü bir bölgede kıyı ile iç kesimler arasındaki ulaşım hakkında aşağıdakilerden hangisi söylenebilir?', 'Ulaşım zordur ve genellikle geçitler veya tüneller aracılığıyla sağlanır', ['Doğal oluklar sayesinde iç kesimlere ulaşım çok kolaydır', 'Demiryolu ağları kıyıdaki tüm limanlara engelsiz bağlanır', 'Denizel iklim etkisi yüzlerce kilometre içeriye rahatça sokulur'], 'Dağlar kıyıya paralel uzandığı için kıyı ile iç kesim arasına doğal bir duvar çeker ve ulaşım maliyetini artırır.'),
  ('Enine kıyı tipinin hakim olduğu Ege kıyılarında denizden gelen nemli hava kütlelerinin iç kesimlere kadar sokulabilmesinin nedeni nedir?', 'Dağların kıyıya dik uzanması ve aralarında geniş çöküntü ovalarının bulunması', ['Kıyıda yüksek falez duvarlarının rüzgar hızını artırması', 'Deniz suyu sıcaklığının yıl boyunca değişmemesi', 'Gelgit akıntılarının nehir vadileri boyunca karaya ilerlemesi'], 'Graben olukları kıyıya dik açıldığı için ılıman ve nemli deniz etkisi iç kesimlere kolayca ulaşır.'),
  ('Örtü buzullarının oluşturduğu hörgüçkaya ve moren tepelerinin deniz suları altında kalmasıyla binlerce küçük adacığın ortaya çıktığı kıyı tipine ne denir?', 'Skyer kıyı', ['Watt kıyı', 'Limanlı kıyı', 'Enine kıyı'], 'Finlandiya ve İsveç\'in Baltık kıyılarında yaygın olan skyer kıyıları, buzul aşınım-birikim düzlüklerinin sular altında kalmasıyla oluşur.'),
  ('Karadeniz\'in kuzeyinde (Ukrayna, Odessa çevresi) geniş vadilerin deniz altında kalıp önlerinin kıyı kordonlarıyla kapanmasıyla oluşan kıyı tipi hangisidir?', 'Limanlı kıyı', ['Fiyortlu kıyı', 'Dalmaçya kıyı', 'Mercanlı kıyı'], 'Alçak platolardaki geniş akarsu ağızlarının boğulup kıyı oklarıyla yarı kapalı hale gelmesi limanlı kıyı tipini oluşturur.'),
  ('Bir ülkenin haritasında kıyı gerçek uzunluğu ile kuş uçuşu kıyı uzunluğu arasındaki farkın çok fazla olması hangi kıyı tiplerinin varlığına işaret eder?', 'Enine veya fiyort tipi kıyılar', ['Boyuna veya düz kıyılar', 'Yalnızca falezli dik kıyılar', 'Abrazyon düzlüğü kıyıları'], 'Girinti, çıkıntı, koy ve körfez sayısı arttıkça (enine, ria, fiyort kıyıları) gerçek kıyı uzunluğu ile kuş uçuşu uzunluk arasındaki fark büyür.'),
  ('Tropikal kuşaktaki sıcak ve temiz sığ denizlerde kalker iskeletli deniz canlılarının kalıntılarının birikmesiyle oluşan kıyı tipine ne ad verilir?', 'Mercanlı (Resifli) kıyı', ['Watt kıyı', 'Skyer kıyı', 'Fiyort kıyı'], 'Avustralya\'nın kuzeydoğusundaki Büyük Set Resifi mercanlı kıyıların dünyadaki en büyük örneğidir.'),
  ('Boyuna kıyılarda kıta sahanlığının (şelf alanının) genel olarak dar olmasının kıyı şekillenmesi üzerindeki en önemli sonucu nedir?', 'Delta oluşumunun zorlaşması ve falezlerin yaygınlaşması', ['Lagün ve tomboloların her koyda hızla oluşması', 'Gelgit genliğinin birkaç metre yükselmesi', 'Kıyı önünde yüzlerce adanın dizilmesi'], 'Derin kıyılarda akarsuların getirdiği alüvyonlar tabana gömüldüğü için delta zor oluşur, dalga aşındırmasıyla falezler gelişir.'),
  ('Buzulların oluşturduğu U profilli vadilere coğrafyada verilen diğer ad aşağıdakilerden hangisidir?', 'Tekne vadi', ['Çentik vadi', 'Boğaz vadi', 'Kanyon vadi'], 'Tabanı düzleşmiş ve yamaçları dikleşmiş buzul vadileri tekneye benzediği için tekne vadi olarak da adlandırılır.'),
  ('Dalga aşındırmasıyla oluşan falezlerin Türkçe karşılığı olan eş anlamlı kavram hangisidir?', 'Yalıyar', ['Deniz kulağı', 'Saplı ada', 'Buzultaş'], 'Falez kelimesinin Türkçe coğrafya terminolojisindeki karşılığı yalıyardır.'),
  ('Lagün göllerine Türkçe coğrafya kaynaklarında verilen diğer ad aşağıdakilerden hangisidir?', 'Deniz kulağı', ['Buzul çanağı', 'Kıyı taraçası', 'Hörgüçkaya'], 'Kıyı kordonlarıyla denizden ayrılan lagünler kıyı set gölü veya deniz kulağı olarak da bilinir.'),
  ('Tombolo şekline görünümünden dolayı verilen Türkçe ad aşağıdakilerden hangisidir?', 'Saplı ada', ['Yalıyar', 'Deniz kulağı', 'Tekne vadi'], 'Kıyı oku adayı karaya bir sap gibi bağladığı için tomboloya saplı ada denir.'),
  ('Moren depolarına coğrafyada verilen Türkçe karşılık aşağıdakilerden hangisidir?', 'Buzultaş', ['Yalıyar', 'Kırgıbayır', 'Şahitkaya'], 'Buzulların taşıyıp biriktirdiği taş ve toprak yığınlarına buzultaş (moren) adı verilir.'),
  ('Yeryüzünde tatlı su kaynaklarının en büyük bölümünü barındıran Antarktika ve Grönland\'daki dev buz kütleleri hangi buzul türüne girer?', 'Örtü (Kıta) buzulu', ['Sirk buzulu', 'Vadi buzulu', 'Takke buzulu'], 'Kıtaları veya çok geniş kara parçalarını binlerce metre kalınlıkta tamamen kaplayan buzullara örtü buzulu denir.'),
  ('Dağların yalnızca zirve kesimlerini bir şapka gibi örten, vadi içlerine kollar halinde uzanmayan buzullara ne ad verilir?', 'Takke buzulu', ['Örtü buzulu', 'Bankiz', 'Aysberg'], 'Ağrı Dağı\'nın doruğunda olduğu gibi zirveyi kubbe biçiminde saran buzullara takke (doruk) buzulu denir.'),
];
